/* Generated by `helix system machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type SelectionContext, type SelectionInput, clears, differs, handOn, hold, replaceable, seed, seedable, take, unchosen } from './machine.js'

export type { SelectionContext, SelectionInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'singleSelection'

/** The state `settled`. */
export const STATE_SETTLED = 0
/** The state `unresolved`. */
export const STATE_UNRESOLVED = 1
/** Each state's name, by its number. */
export const STATES = ['settled', 'unresolved'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['settled', 'unresolved'] as const

/** The event `CHOOSE`. */
export const EVENT_CHOOSE = 0
/** The event `ITEMS`. */
export const EVENT_ITEMS = 1
/** The event `SEED`. */
export const EVENT_SEED = 2
/** Each event's name, by its number. */
export const EVENTS = ['CHOOSE', 'ITEMS', 'SEED'] as const

/** The effect `announce`. */
export const EFFECT_ANNOUNCE = 0
/** Each effect's name, by its number. */
export const EFFECTS = ['announce'] as const

/** The request event `activate`. */
export const ASK_ACTIVATE = 0
/** Each request event's name, by its number. */
export const ASKS = ['activate'] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: SelectionContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (context: SelectionContext): number =>
  unchosen(context) ? STATE_UNRESOLVED : STATE_SETTLED

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (_state: number): readonly Effect[] => []

/** What `settled` does with each event. */
const inSettled = (context: SelectionContext, event: number, input: SelectionInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_CHOOSE:
      return clears(context, input) ? { accept: { context: take(context, input), effects: [[EFFECT_ANNOUNCE]], state: STATE_UNRESOLVED }, ask: [ASK_ACTIVATE], refuse: { context: context, effects: [], state: STATE_SETTLED } } : differs(context, input) ? { accept: { context: take(context, input), effects: [[EFFECT_ANNOUNCE]], state: STATE_SETTLED }, ask: [ASK_ACTIVATE], refuse: { context: context, effects: [], state: STATE_SETTLED } } : undefined
    case EVENT_ITEMS:
      return replaceable(context, input) ? { context: handOn(context, input), effects: [[EFFECT_ANNOUNCE]], state: STATE_SETTLED } : { context: hold(context, input), effects: [], state: STATE_SETTLED }
  }
  return undefined
}

/** What `unresolved` does with each event. */
const inUnresolved = (context: SelectionContext, event: number, input: SelectionInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_CHOOSE:
      return differs(context, input) ? { accept: { context: take(context, input), effects: [[EFFECT_ANNOUNCE]], state: STATE_SETTLED }, ask: [ASK_ACTIVATE], refuse: { context: context, effects: [], state: STATE_UNRESOLVED } } : undefined
    case EVENT_ITEMS:
      return { context: hold(context, input), effects: [], state: STATE_UNRESOLVED }
    case EVENT_SEED:
      return seedable(context, input) ? { context: seed(context, input), effects: [], state: STATE_SETTLED } : undefined
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: SelectionContext, event: number, input: SelectionInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_SETTLED:
      return inSettled(context, event, input)
    case STATE_UNRESOLVED:
      return inUnresolved(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (_state: number, _context: SelectionContext, _owner: number): Move | undefined =>
  undefined

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: SelectionContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
